import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { mockId } from '@shared/testing/mock'

export const CreateKitInputSchema = z.object({
	storeId: z.uuid(),
	name: z.string(),
	type: z.enum(ProductCostType),
	shipping: z.number(),
	cost: z.number().optional(),
	items: z.array(
		z.object({
			productId: z.uuid(),
			quantity: z.number(),
			quantityModifier: z.enum(QuantityModifier),
		}),
	),
})

export const CreateKitOutputSchema = z.object({
	id: z.uuid(),
	success: z.boolean(),
})

/** MOCK. Create a kit (wizard command). Returns static success. */
@injectable()
export class CreateKit extends Handler<typeof CreateKitInputSchema, typeof CreateKitOutputSchema> {
	readonly name = 'create_kit' as const
	readonly inputSchema = CreateKitInputSchema
	readonly outputSchema = CreateKitOutputSchema

	protected async handle(_input: this['input']): Promise<this['output']> {
		return { id: mockId(), success: true }
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateKitInputSchema = z.object({
	storeId: z.uuid(),
	id: z.uuid(),
	name: z.string().optional(),
	shipping: z.number().optional(),
	cost: z.number().optional(),
	items: z
		.array(
			z.object({
				productId: z.uuid(),
				quantity: z.number(),
				quantityModifier: z.enum(QuantityModifier),
			}),
		)
		.optional(),
})

export const UpdateKitOutputSchema = z.object({
	id: z.uuid(),
	success: z.boolean(),
})

/** MOCK. Update an existing kit (wizard edit command). Returns static success. */
@injectable()
export class UpdateKit extends Handler<typeof UpdateKitInputSchema, typeof UpdateKitOutputSchema> {
	readonly name = 'update_kit' as const
	readonly inputSchema = UpdateKitInputSchema
	readonly outputSchema = UpdateKitOutputSchema

	protected async handle(input: this['input']): Promise<this['output']> {
		return { id: input.id, success: true }
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'

export const DeleteKitInputSchema = z.object({
	storeId: z.uuid(),
	ids: z.array(z.uuid()).min(1),
})

export const DeleteKitOutputSchema = z.object({
	deleted: z.number(),
	success: z.boolean(),
})

/** MOCK. Delete kits by ids (bulk toolbar command). Returns static success. */
@injectable()
export class DeleteKit extends Handler<typeof DeleteKitInputSchema, typeof DeleteKitOutputSchema> {
	readonly name = 'delete_kit' as const
	readonly inputSchema = DeleteKitInputSchema
	readonly outputSchema = DeleteKitOutputSchema

	protected async handle(input: this['input']): Promise<this['output']> {
		return { deleted: input.ids.length, success: true }
	}
}

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { CreateKit, CreateKitInputSchema, CreateKitOutputSchema } from '../usecases/CreateKit'

export const CreateKitControllerInputSchema = z.object({
	ctx: z.object({ session: z.object({ storeId: z.uuid() }) }),
	body: CreateKitInputSchema.omit({ storeId: true }),
})

export const CreateKitControllerOutputSchema = CreateKitOutputSchema

@injectable()
export class CreateKitController extends Controller<typeof CreateKitControllerInputSchema, typeof CreateKitControllerOutputSchema> {
	readonly path = '/catalog/kits'
	readonly method = 'post' as const
	readonly description = 'MOCK. Create a kit (wizard command).'
	readonly inputSchema = CreateKitControllerInputSchema
	readonly outputSchema = CreateKitControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private command: CreateKit) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		return {
			status: HttpStatusCode.OK,
			data: await this.command.execute({
				storeId: request.ctx.session.storeId,
				...request.body,
			}),
		}
	}
}

