import { useState, type ReactNode } from 'react'
import { useTranslation } from 'react-i18next'
import { Popover, PopoverTrigger, PopoverContent, PopoverTitle } from '@/components/ui/popover'
import { Combobox, ComboboxSelectTrigger, ComboboxContent, ComboboxList, ComboboxItem } from '@/components/ui/combobox'
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group'
import { Button } from '@/components/ui/button'

const currencies = [
	{ code: 'BRL', flag: '🇧🇷' },
	{ code: 'USD', flag: '🇺🇸' },
	{ code: 'EUR', flag: '🇪🇺' },
]

function parsePtBRNumber(raw: string): number {
	return parseFloat(raw.replace(',', '.')) || 0
}

function formatForInput(value: number): string {
	return value.toFixed(2).replace('.', ',')
}

interface Product {
	name: string
	imageUrl: string
}

interface EditProductCostPopoverProps {
	label: string
	currentValue: number
	products: Product[]
	onSave: (totalCost: number) => void
	children: ReactNode
}

export function EditProductCostPopover({ label, currentValue, products, onSave, children }: EditProductCostPopoverProps) {
	const { t } = useTranslation()
	const [open, setOpen] = useState(false)
	const [productValues, setProductValues] = useState<string[]>([])
	const [productCurrencies, setProductCurrencies] = useState<(string | null)[]>([])

	const handleOpen = (isOpen: boolean) => {
		if (isOpen) {
			const perProduct = products.length > 0 ? currentValue / products.length : currentValue
			setProductValues(products.map(() => formatForInput(perProduct)))
			setProductCurrencies(products.map(() => 'BRL'))
		}
		setOpen(isOpen)
	}

	const updateProductValue = (index: number, value: string) => {
		setProductValues(prev => {
			const next = [...prev]
			next[index] = value
			return next
		})
	}

	const updateProductCurrency = (index: number, currency: string | null) => {
		setProductCurrencies(prev => {
			const next = [...prev]
			next[index] = currency
			return next
		})
	}

	const handleSave = () => {
		const total = productValues.reduce((sum, v) => sum + parsePtBRNumber(v), 0)
		onSave(total)
		setOpen(false)
	}

	return (
		<Popover open={open} onOpenChange={handleOpen}>
			<PopoverTrigger render={<span />}>{children}</PopoverTrigger>
			<PopoverContent className="w-auto min-w-[360px]" side="bottom" align="start">
				<PopoverTitle className="text-xs text-muted-foreground">{label}</PopoverTitle>
				<div className="flex flex-col gap-2">
					{products.map((product, i) => {
						const selected = currencies.find(c => c.code === productCurrencies[i])
						return (
							<div key={i} className="flex items-center gap-2">
								<img src={product.imageUrl} alt={product.name} className="size-7 shrink-0 rounded-full object-cover" title={product.name} />
								<Combobox value={productCurrencies[i]} onValueChange={v => updateProductCurrency(i, v)}>
									<ComboboxSelectTrigger size="sm">
										{selected?.flag} {selected?.code ?? 'BRL'}
									</ComboboxSelectTrigger>
									<ComboboxContent>
										<ComboboxList>
											{currencies.map(c => (
												<ComboboxItem key={c.code} value={c.code}>
													{c.flag} {c.code}
												</ComboboxItem>
											))}
										</ComboboxList>
									</ComboboxContent>
								</Combobox>
								<InputGroup className="flex-1">
									<InputGroupAddon align="inline-start">
										<span className="text-xs text-muted-foreground">$</span>
									</InputGroupAddon>
									<InputGroupInput
										value={productValues[i]}
										onChange={e => updateProductValue(i, e.target.value)}
										onKeyDown={e => e.key === 'Enter' && handleSave()}
										className="text-sm"
									/>
								</InputGroup>
							</div>
						)
					})}
					<Button size="sm" className="w-full" onClick={handleSave}>
						{t('orders.edit.save')}
					</Button>
				</div>
			</PopoverContent>
		</Popover>
	)
}

