"use client";
import { parseAsArrayOf, parseAsString, useQueryState } from "nuqs";
import { useMemo } from "react";
import Skeleton from "react-loading-skeleton";
import { valueToGenericCurrencyString } from "@/hooks/currencies/useCurrencyConversion";
import { useListProductCosts } from "@/lib/api/queries/productCosts/listProductCosts";
import type { Currency } from "~/enum/currency";
import type { ProductCostTableEntry } from "./types";

interface CostRangeProps {
	product: ProductCostTableEntry;
}

export default function CostRange({ product }: CostRangeProps) {
	const [country] = useQueryState("country", parseAsString.withDefault(""));
	const [checkedFilters] = useQueryState(
		"filters",
		parseAsArrayOf(parseAsString).withDefault([]),
	);

	const onlyFilled = useMemo(
		() => checkedFilters.includes("registered:yes"),
		[checkedFilters],
	);

	const { data: productCostData, isLoading } = useListProductCosts({
		country,
		mapKey: "productId",
		onlyFilled,
	});

	const text = useMemo(() => {
		if (isLoading) {
			return;
		}

		const costData = productCostData?.data[product.id];
		if (!costData || costData.costs.length === 0) {
			return "Sem custos registrados";
		}

		const costs = {} as Record<
			"min" | "max",
			{ currency: Currency; value: number }
		>;

		for (const { currency, cost } of costData.costs) {
			const costObj = { currency, value: cost };

			if (!costs.min || cost < costs.min.value) {
				costs.min = costObj;
			}
			if (!costs.max || cost > costs.max.value) {
				costs.max = costObj;
			}
		}

		const minStr = valueToGenericCurrencyString(
			costs.min.value,
			costs.min.currency,
		);
		let rangeText = minStr;

		if (costs.min.value !== costs.max.value) {
			const maxStr = valueToGenericCurrencyString(
				costs.max.value,
				costs.max.currency,
			);
			rangeText += ` - ${maxStr}`;
		}

		return rangeText;
	}, [isLoading, product, productCostData]);

	if (isLoading) {
		return <Skeleton height="1rem" width="6rem" />;
	}

	return <>{text}</>;
}

import ConfirmationButton from "@/components/simple/ConfirmationButton";
import {
	type Dispatch,
	type ReactNode,
	type SetStateAction,
	useState,
} from "react";
import Button from "~/components/simple/Button";
import useNotificationActions from "~/stateManagement/actions/useNotificationActions";
import { useUploadProductCostsCSVMutation } from "~/stateManagement/reducers/queries/api";
import ProductCostCSVUploadModal from "../ProductCostCSVUploadModal";
import { CountryFilter } from "./CountryFilter";

export interface ProductCostTableBeforeProps {
	children: ReactNode;
	compact?: boolean;
	countries: string[];
	deleteAllLabel: string;
	isDeleteDisabled: boolean;
	isLoading: boolean;
	onDelete: () => Promise<void>;
	refetch: () => void;
	setFilters?: Dispatch<SetStateAction<string[]>>;
}

export function ProductCostTableBefore({
	children,
	compact = false,
	deleteAllLabel,
	isDeleteDisabled,
	isLoading,
	onDelete,
	refetch,
	...countryFilterProps
}: ProductCostTableBeforeProps) {
	const { notify } = useNotificationActions();
	const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
	const [uploadCSV, { isLoading: isUploadingCSV }] =
		useUploadProductCostsCSVMutation();

	const handleUploadCSV = async (file: File) => {
		try {
			await uploadCSV(file).unwrap();
			notify(
				"CSV enviado com sucesso",
				"success",
				"Os custos estão sendo processados e podem demorar alguns segundos para aparecer.",
			);
			refetch();
		} catch (error) {
			notify(
				"Erro ao enviar CSV",
				"error",
				"Não foi possível processar o arquivo CSV. Verifique o formato e tente novamente.",
			);
			throw error;
		}
	};

	return (
		<div className="flex flex-col gap-4">
			<div className="flex gap-4" style={{ ...(compact && {}) }}>
				{compact && <CountryFilter {...countryFilterProps} />}
				{children}
				<div
					className="flex items-center"
					style={{
						gap: "1rem",
						...(compact && {
							borderLeft: "1px solid #ffffff15",
							marginLeft: "auto",
							paddingLeft: "1rem",
						}),
					}}
				>
					<Button
						iconName="upload"
						type="tertiary"
						size="small"
						label="Importar por CSV"
						onClick={() => setIsUploadModalOpen(true)}
					/>
					<ConfirmationButton
						disabled={isDeleteDisabled}
						iconName="trash"
						isLoading={isLoading}
						label={deleteAllLabel}
						message="Os custos registrados para todas as variantes deste produto serão deletados. Essa ação não pode ser desfeita."
						onClick={onDelete}
						size="small"
						style={{ width: "16.5rem" }}
						title="Deseja deletar todos os custos?"
						type="tertiary"
					/>
				</div>
			</div>

			{!compact && <CountryFilter {...countryFilterProps} />}

			<ProductCostCSVUploadModal
				isOpen={isUploadModalOpen}
				onClose={() => setIsUploadModalOpen(false)}
				onUpload={handleUploadCSV}
				isLoading={isUploadingCSV}
			/>
		</div>
	);
}

import { updateTableFilter } from "@/components/Table/utils";
import Button from "@/components/simple/Button";
import i18nCountries from "i18n-iso-countries";
import enCountries from "i18n-iso-countries/langs/en.json";
import { parseAsString, useQueryState } from "nuqs";
import { useMemo, type CSSProperties } from "react";
import { ButtonLimiter } from "~/app/app/settings/integration/style";
import { filterOptions } from "../../constants";
import type { ProductCostTableBeforeProps } from "./Before";

i18nCountries.registerLocale(enCountries);

export type CountryFilterProps = Pick<
	ProductCostTableBeforeProps,
	"countries" | "setFilters"
> & {
	style?: CSSProperties;
};

export function CountryFilter({
	countries,
	setFilters,
	style,
}: CountryFilterProps) {
	const [country, setCountry] = useQueryState(
		"country",
		parseAsString.withDefault(""),
	);

	const countryInfo = useMemo(
		() => [
			["", "Global"],
			...countries
				.map((each) => [each, i18nCountries.getName(each, "en")!])
				.sort(([, a], [, b]) => a.localeCompare(b, "en")),
		],
		[countries],
	);

	return (
		<div className="w-full rounded-[8px] bg-[#1f212a] p-2" style={style}>
			<div className="grid w-fit auto-cols-fr grid-flow-col justify-start gap-4">
				{countryInfo.map(([countryCode, countryName]) => {
					const selected = countryCode === country;

					return (
						<ButtonLimiter
							className="flex items-center"
							key={countryCode}
							selected={selected}
						>
							<Button
								className="h-full w-full min-w-30"
								label={countryName}
								onClick={() => {
									setCountry((!selected && countryCode) || null);

									if (setFilters) {
										updateTableFilter(
											setFilters,
											filterOptions[0].value,
											countryCode === "" || selected
												? undefined
												: filterOptions[0].children![0].value,
										);
									}
								}}
								type="tertiary"
							/>
						</ButtonLimiter>
					);
				})}
			</div>
		</div>
	);
}

