import { Auth, UserOnly } from "@decorators";
import {
	BadRequestException,
	Body,
	Controller,
	Delete,
	Get,
	Param,
	Post,
	Put,
	Query,
	Req,
} from "@nestjs/common";
import { EventEmitter2 } from "@nestjs/event-emitter";
import { ApiBody, ApiConsumes, ApiOkResponse, ApiTags } from "@nestjs/swagger";
import { AuthData } from "@shared/types";
import { BaseUtils } from "@shared/utils";
import { pick } from "es-toolkit";
import { FastifyRequest } from "fastify";
import { ProductCost } from "sql";
import {
	CreateProductCostBody,
	DeleteProductCostQuery,
	GetProductCostsSummaryQuery,
	ListProductCostsQuery,
	ListProductCostsReturn,
	UpdateProductCostDTO,
} from "../dtos";
import { CreateProductCostBulkBody } from "../dtos/CreateProductCostBulk";
import { FixProductCostsQuery } from "../dtos/FixProductCosts";
import { GetKitCostsSummaryReturn, GetProductCostsSummaryReturn } from "../dtos/GetProductCostsSummary";
import { FixProductCostsEvent, ProductCostCreatedEvent, ProductCostDeletedEvent } from "../events";
import {
	CreateProductCost,
	CreateProductCostBulk,
	DeleteProductCost,
	FindProductCost,
	GenerateProductCostCsv,
	GetKitCostsSummary,
	GetProductCostsSummary,
	ListProductCosts,
	ProcessProductCostCsv,
	UpdateProductCost,
} from "../services";

@ApiTags("Products")
@Controller(["productCosts", "kits", "variantCosts"])
export class ProductCostsController {
	constructor(
		private readonly baseUtils: BaseUtils,
		private readonly createProductCost: CreateProductCost,
		private readonly createProductCostBulk: CreateProductCostBulk,
		private readonly deleteProductCost: DeleteProductCost,
		private readonly eventEmitter: EventEmitter2,
		private readonly findProductCost: FindProductCost,
		private readonly generateProductCostCsv: GenerateProductCostCsv,
		private readonly getKitCostsSummary: GetKitCostsSummary,
		private readonly getProductCostsSummary: GetProductCostsSummary,
		private readonly listProductCosts: ListProductCosts,
		private readonly processProductCostCsv: ProcessProductCostCsv,
		private readonly updateProductCost: UpdateProductCost,
	) {}

	@ApiOkResponse({ type: ListProductCostsReturn })
	@Get()
	async list(
		@Auth() { credentials }: AuthData,
		@Query() query: ListProductCostsQuery,
	): Promise<ListProductCostsReturn> {
		const productCosts = await this.listProductCosts.execute({
			credentials,
			...query,
		});

		return productCosts;
	}

	@Post()
	async create(@Auth() { credentials }: AuthData, @Body() body: CreateProductCostBody): Promise<ProductCost> {
		const productCost = await this.createProductCost.execute({
			credentials,
			...body,
		});

		const items = productCost.options.flatMap(o => o.items);

		const productIds = Array.from(new Set(items.map(i => i.productId))) as string[];
		const variantIds = Array.from(new Set(items.flatMap(i => i.variants))) as string[];

		this.eventEmitter.emit(
			...new ProductCostCreatedEvent({
				endDate: new Date(),
				productIds,
				variantIds,
				virtualStoreId: credentials.current.virtualStoreId,
			}).toArgs(),
		);

		return productCost;
	}

	@Post("bulk")
	async createBulk(
		@Auth() { credentials }: AuthData,
		@Body() body: CreateProductCostBulkBody,
	): Promise<ProductCost[]> {
		const productCosts = await this.createProductCostBulk.execute({
			credentials,
			...body,
		});

		const items = productCosts.flatMap(c => c.options).flatMap(o => o.items);

		const productIds = Array.from(new Set(items.map(i => i.productId)));
		const variantIds = Array.from(new Set(items.flatMap(i => i.variants)));

		this.eventEmitter.emit(
			...new ProductCostCreatedEvent({
				productIds,
				variantIds,
				virtualStoreId: credentials.current.virtualStoreId,
			}).toArgs(),
		);

		return productCosts;
	}

	@Get("csv")
	@ApiOkResponse({ type: String })
	async generateCsv(@Auth() { credentials }: AuthData): Promise<string> {
		const csv = await this.generateProductCostCsv.execute(credentials);

		return csv;
	}

	@Post(["csv", "bulk/csv"])
	@ApiConsumes("multipart/form-data")
	@ApiBody({
		schema: {
			properties: {
				file: {
					format: "binary",
					type: "string",
				},
			},
			required: ["file"],
			type: "object",
		},
	})
	async createBulkFromCsv(
		@Auth() { credentials }: AuthData,
		@Req() req: FastifyRequest,
	): Promise<ProductCost[]> {
		if (!req.isMultipart()) {
			throw new BadRequestException("Request deve ser multipart/form-data");
		}

		let csvContent = "";

		const file = (req.body as any)?.file;
		if (file) {
			if (file.toBuffer) {
				csvContent = (await file.toBuffer()).toString("utf-8");
			} else if (Buffer.isBuffer(file)) {
				csvContent = file.toString("utf-8");
			}
		}

		if (!csvContent) {
			for await (const part of req.parts()) {
				if (part.type === "file" && part.fieldname === "file") {
					const chunks: Buffer[] = [];
					for await (const chunk of part.file) chunks.push(chunk);
					csvContent = Buffer.concat(chunks).toString("utf-8");
					break;
				}
			}
		}

		if (!csvContent) {
			throw new BadRequestException("Arquivo não encontrado");
		}

		const productCosts = await this.processProductCostCsv.execute({
			credentials,
			csvContent,
		});

		const items = productCosts.flatMap(c => c.options).flatMap(o => o.items);
		const productIds = [...new Set(items.map(i => i.productId))];
		const variantIds = [...new Set(items.flatMap(i => i.variants))];

		if (productIds.length || variantIds.length) {
			this.eventEmitter.emit(
				...new ProductCostCreatedEvent({
					endDate: new Date(),
					productIds,
					variantIds,
					virtualStoreId: credentials.current.virtualStoreId,
				}).toArgs(),
			);
		}

		return productCosts;
	}

	@Delete()
	async delete(
		@Auth() {
			credentials: {
				current: { integrationSetId, virtualStoreId },
			},
		}: AuthData,
		@Query() query: DeleteProductCostQuery,
	): Promise<object> {
		const { productIds, variantIds } = await this.deleteProductCost.execute({
			integrationSetId,
			...query,
		});

		if (productIds?.length || variantIds?.length) {
			this.eventEmitter.emit(
				...new ProductCostDeletedEvent({
					endDate: new Date(),
					productIds,
					variantIds,
					virtualStoreId,
				}).toArgs(),
			);
		}

		return {};
	}

	@Get("fix")
	@UserOnly()
	async fix(
		@Auth() {
			credentials: {
				current: { virtualStoreId },
			},
		}: AuthData,
		@Query() { emails = [], faulty }: FixProductCostsQuery,
	): Promise<void> {
		const virtualStoreIds = await this.baseUtils.getVirtualStoreIds({
			emails,
		});
		if (virtualStoreId) virtualStoreIds.push(virtualStoreId);

		console.log(virtualStoreIds);
		virtualStoreIds.forEach(virtualStoreId =>
			this.eventEmitter.emit(
				...new FixProductCostsEvent({
					faulty,
					virtualStoreId,
				}).toArgs(),
			),
		);
	}

	@Get("summary")
	@ApiOkResponse({ type: GetProductCostsSummaryReturn })
	async getSummary(
		@Auth() {
			credentials: {
				current: { integrationSetId },
			},
		}: AuthData,
		@Query() query: GetProductCostsSummaryQuery,
	): Promise<GetProductCostsSummaryReturn> {
