			...query,
			integrationSetId,
			type: ["KIT"],
		});

		return summary;
	}

	@Get(":id")
	async getSingle(
		@Auth() {
			credentials: {
				current: { integrationSetId },
			},
		}: AuthData,
		@Param("id") id: string,
	): Promise<ProductCost> {
		const kit = await this.findProductCost.execute({
			id,
			integrationSetId,
		});

		return kit;
	}

	@Put()
	async updateSingle(
		@Auth() {
			credentials: {
				current: { virtualStoreId },
			},
		}: AuthData,
		@Body() body: UpdateProductCostDTO,
	): Promise<ProductCost> {
		const updatedProductCost = await this.updateProductCost.execute(body);

		const [costOption] = updatedProductCost.options;
		const { items } = costOption;

		const productIds = Array.from(new Set(items.map(i => i.productId)));
		const variantIds = Array.from(new Set(items.flatMap(i => i.variants)));

		this.eventEmitter.emit(
			...new ProductCostCreatedEvent({
				productIds,
				variantIds,
				virtualStoreId,
				...pick(costOption, ["startDate", "endDate"]),
			}).toArgs(),
		);

		return updatedProductCost;
	}
}

import { PrismaService } from "@infra";
import { Product, ProductDocument } from "@modules/integrationSets/submodules/product/schemas/product.schema";
import { HttpException, HttpStatus, Injectable } from "@nestjs/common";
import { InjectModel } from "@nestjs/mongoose";
import { Sort, TotalByCurrency } from "@shared/types";
import { BaseUtils } from "@shared/utils";
import { TraceClass } from "@utils/tracing";
import Decimal from "decimal.js";
import { Model } from "mongoose";
import { ProductCostType } from "sql";
import { GetKitCostsSummaryReturn, GetProductCostsSummaryDTO, SortKeys } from "../dtos";
import { GetProductCostsSummarySort } from "../types";
import { findSingleCosts } from "../utils/funcs";

type Data = GetKitCostsSummaryReturn["data"];

// Todo: check for MULTIPLE
@Injectable()
@TraceClass()
export class GetKitCostsSummary {
	constructor(
		private readonly baseUtils: BaseUtils,
		private readonly prisma: PrismaService,
		@InjectModel(Product.name)
		private readonly productModel: Model<ProductDocument>,
	) {}

	async execute({
		integrationSetId,
		limit,
		page,
		search,
		sort = "NAME",
		sortOrder,
		type,
	}: GetProductCostsSummaryDTO): Promise<GetKitCostsSummaryReturn> {
		if (type.includes("SINGLE")) {
			throw new HttpException(
				"Você não pode listar custos de produto único com kits ao mesmo tempo.",
				HttpStatus.BAD_REQUEST,
			);
		}

		const isFetchingKits = type.includes("KIT");

		const [virtualStoreId] = await this.baseUtils.getVirtualStoreIds({
			ids: [integrationSetId],
		});

		let costs = await this.prisma.productCost.findMany({
			orderBy: {
				createdAt: "desc",
			},
			select: {
				createdAt: true,
				id: true,
				name: true,
				options: {
					orderBy: {
						createdAt: "desc",
					},
					select: {
						country: true,
						createdAt: true,
						currency: true,
						endDate: true,
						id: true,
						items: {
							select: {
								id: true,
								price: true,
								productId: true,
								quantity: true,
								quantityModifier: true,
								shipping: true,
								variants: true,
								variantsHash: true,
							},
						},
						price: true,
						shipping: true,
						startDate: true,
					},
				},
				type: true,
			},
			where: {
				...(isFetchingKits && {
					type: {
						in: [ProductCostType.MULTIPLE, ProductCostType.SINGLE],
					},
				}),
				virtualStoreId,
			},
		});

		// Filter
		const filters: ((data: (typeof costs)[number]) => boolean)[] = [];

		if (isFetchingKits) {
			const singleCosts = findSingleCosts(costs.flatMap(cost => cost.options));

			costs.forEach(cost => {
				if (cost.type === "MULTIPLE") {
					return;
				}

				cost.options = cost.options.filter(option => {
					option.items = option.items.filter(
						item =>
							item.quantity > 1 ||
							item.quantityModifier !== "EQ" ||
							singleCosts.get(item.variantsHash!) === false,
					);

					return option.items.length > 0;
				});
			});

			filters.push(cost => cost.options.length > 0);
		}

		costs = costs.filter(each => filters.every(filter => filter(each)));
		const total = costs.length;

		const products = await this.productModel.aggregate([
			{
				$match: {
					externalId: {
						$in: costs.flatMap(({ options }) =>
							options.flatMap(({ items }) => {
								return items.map(item => item.productId);
							}),
						),
					},
					...(search && {
						name: {
							$options: "i",
							$regex: search,
						},
					}),
				},
			},
			{
				$lookup: {
					as: "pictureDoc",
					foreignField: "_id",
					from: "pictures",
					localField: "picture",
				},
			},
			{
				$project: {
					_id: 0,
					id: "$externalId",
					name: 1,
					picture: {
						$ifNull: [{ $arrayElemAt: ["$pictureDoc.src", 0] }, "$pictureUrl", null],
					},
				},
			},
		]);

		const productsMap = new Map<string, Record<string, any> | undefined>(
			products.map(product => [String(product.id), product]),
		);

		const data = costs
			.sort(this.sortData(sort, sortOrder))
			.slice((page - 1) * limit, page * limit)
			.map<Data[number]>(({ name, options, type, ...costData }) => {
				const isMultipleProductsCost = type === "MULTIPLE";

				return {
					...costData,
					name: name!,
					options: options.map(({ currency, items, price, shipping, ...optionData }) => ({
						...optionData,
						...(isMultipleProductsCost && this.generateCostField(currency, price, shipping)),
						products: items.reduce((obj, { price, productId, shipping, variantsHash, ...itemData }) => {
							obj[productId] ??= [];

							const product = productsMap.get(productId);
							if (product) {
								const { name, picture } = product;

								obj[productId].push({
									...(!isMultipleProductsCost && this.generateCostField(currency, price, shipping)),
									...itemData,
									name,
									picture,
								});
							}

							return obj;
						}, {}),
					})),
					type,
				};
			});

		return {
			data,
			pages: Math.ceil(total / limit),
			total,
		};
	}

	private sortData<T = Record<string, any>>(sort: SortKeys, sortOrder: Sort): (a: T, b: T) => number {
		const sortField = (sort && GetProductCostsSummarySort[sort]) || "name";
		const sortFieldIsStr = ["id", "name"].includes(sortField);
		const sortAscending = sortOrder === "ASC";

		return (a, b) => {
			let aValue: string | number | Date = a[sortField];
			let bValue: string | number | Date = b[sortField];

			if (sortFieldIsStr) {
				aValue = String(aValue).toLowerCase();
				bValue = String(bValue).toLowerCase();

				return sortAscending ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
			}

			aValue = Number(aValue);
			bValue = Number(bValue);

			if (aValue === bValue) {
				return 0;
			}

			return sortAscending ? aValue - bValue : bValue - aValue;
		};
	}

	private generateCostField(currency: string, cost: Decimal | null, shipping: Decimal | null) {
		return {
			cost: {
				[currency]: cost?.toNumber(),
			} as TotalByCurrency,
			...(shipping && {
				shipping: {
					[currency]: shipping.toNumber(),
				} as TotalByCurrency,
			}),
		};
	}
}

