import { useProductCostsControllerDelete, useProductCostsControllerGetSummaryKits } from "@lib/api";
import { addYears } from "date-fns";
import { formatInTimeZone } from "date-fns-tz";
import { parseAsString, useQueryState } from "nuqs";
import { useCallback, useMemo, useState } from "react";
import { TableEditButton } from "@/components/compound/EditButton";
import EditKitModal from "@/components/compound/EditKitModal";
import type { Column } from "@/components/compound/Table";
import KitsTableProducts from "@/components/simple/KitsTableProducts";
import ProductImageStack from "@/components/simple/ProductImageStack";
import TextCenter from "@/components/simple/TextCenter";
import useCurrencyConversion from "@/hooks/currencies/useCurrencyConversion";
import useTable from "@/hooks/table/useTable";
import useModalActions from "@/stateManagement/actions/useModalActions";
import useNotificationActions from "@/stateManagement/actions/useNotificationActions";
import type { Kit } from "@/types/entities/kit";
import type { Product } from "@/types/entities/product/product";
import SingleProductKitModal from "~/components/compound/SingleProductKitModal";
import { Currency } from "~/enum/currency";
import { dashboardDateString } from "~/utils/dateTransform";
import { AnnualCost, ProductSubtext } from "./style";

export default function useHandler() {
	const {
		page,
		pageSize,
		selectedRows,
		search,
		sortBy,
		sortOrder,
		onSearch,
		onSelectedRowsChanged,
		onPageChanged,
		onPageSizeChanged,
		setSortBy,
		setSortOrder,
	} = useTable();

	const [country] = useQueryState("country", parseAsString.withDefault(""));

	const queryArgs = useMemo(
		() => ({
			page: page + 1,
			limit: pageSize,
			search,
			sort: sortBy?.toString().toUpperCase(),
			sortOrder: (sortOrder?.toUpperCase() as "ASC" | "DESC") || "DESC",
		}),
		[page, pageSize, search, sortBy, sortOrder],
	);

	const {
		data: summaryResponse,
		isFetching,
		refetch,
	} = useProductCostsControllerGetSummaryKits({
		country,
		limit: queryArgs.limit,
		page: queryArgs.page,
		search: queryArgs.search,
		sortOrder: queryArgs.sortOrder,
	});

	const data = useMemo(() => {
		return {
			data:
				summaryResponse?.data?.map(kit => {
					const sortedOptions =
						kit.options && kit.options.length > 0
							? [...kit.options].sort((a, b) => {
									const dateA = new Date(a.createdAt).getTime();
									const dateB = new Date(b.createdAt).getTime();
									return dateB - dateA;
								})
							: [];
					const option = sortedOptions.length > 0 ? sortedOptions[0] : null;

					if (!option) {
						const defaultDate = new Date();
						const createdAtDate = new Date(kit.createdAt);
						const validCreatedAt = isNaN(createdAtDate.getTime()) ? defaultDate : createdAtDate;
						return {
							_id: kit.id,
							costId: kit.id,
							country: "",
							createdAt: validCreatedAt,
							currency: Currency.USD,
							endDate: addYears(defaultDate, 1000),
							id: kit.id,
							name: kit.name,
							optionId: "",
							price: 0,
							products: [],
							shipping: 0,
							startDate: defaultDate,
							type: kit.type,
							updatedAt: validCreatedAt,
						} as Kit & { type: string; country: string };
					}

					let currency = "BRL";
					let price = 0;
					let shipping = 0;

					if (kit.type === "SINGLE") {
						const firstProductWithCost = Object.values(option.products || {})
							.flat()
							.find(product => product.cost && Object.keys(product.cost).length > 0);

						if (firstProductWithCost?.cost) {
							const costEntries = Object.entries(firstProductWithCost.cost);
							if (costEntries.length > 0) {
								currency = costEntries[0][0];
								price = costEntries[0][1] || 0;
							}
						}

						if (firstProductWithCost?.shipping) {
							const shippingEntries = Object.entries(firstProductWithCost.shipping);
							if (shippingEntries.length > 0) {
								shipping = shippingEntries[0][1] || 0;
							}
						}
					} else {
						const costEntries = option.cost ? Object.entries(option.cost) : [];
						[currency, price] = costEntries[0] || ["USD", 0];

						const shippingEntries = option.shipping ? Object.entries(option.shipping) : [];
						shipping = shippingEntries[0] ? shippingEntries[0][1] : 0;
					}

					const products: Array<{
						_id: string;
						id: string;
						picture: { src: string };
						name: string;
						acceptedVariants: string[];
						count: number;
						quantityModifier?: "EQ" | "GT" | "GTE" | "LT" | "LTE";
						price?: number;
						shipping?: number;
					}> = [];

					Object.entries(option.products || {}).forEach(([productId, productArray]) => {
						productArray.forEach(product => {
							let productPrice: number | undefined;
							let productShipping: number | undefined;

							if (kit.type === "SINGLE" && product.cost) {
								const costEntries = Object.entries(product.cost);
								if (costEntries.length > 0) {
									productPrice = costEntries[0][1] * product.quantity || 0;
								}
							}

							if (kit.type === "SINGLE" && product.shipping) {
								const shippingEntries = Object.entries(product.shipping);
								if (shippingEntries.length > 0) {
									productShipping = shippingEntries[0][1] || 0;
								}
