function QuantityInput({
	tierId,
	quantity,
	onQuantityChange,
}: {
	tierId: string;
	quantity: number;
	onQuantityChange: (id: string, quantity: number) => void;
}) {
	const [localValue, setLocalValue] = useState<string>(`${quantity}x`);
	const wrapperRef = useRef<HTMLDivElement>(null);

	useEffect(() => {
		setLocalValue(`${quantity}x`);
	}, [quantity]);

	useEffect(() => {
		const wrapper = wrapperRef.current;
		if (!wrapper) return;

		const input = wrapper.querySelector("input");
		if (!input) return;

		const handleBlur = () => {
			const numericValue = localValue.replace(/\D/g, "");
			const numValue = Number.parseInt(numericValue, 10);

			if (numericValue === "" || numValue === 0 || Number.isNaN(numValue)) {
				setLocalValue("1x");
				onQuantityChange(tierId, 1);
			}
		};

		input.addEventListener("blur", handleBlur);
		return () => input.removeEventListener("blur", handleBlur);
	}, [localValue, tierId, onQuantityChange]);

	const handleChange = (value: string) => {
		const numericValue = value.replace(/\D/g, "");

		if (numericValue === "") {
			setLocalValue("x");
			onQuantityChange(tierId, 0);
			return;
		}

		const numValue = Number.parseInt(numericValue, 10);
		if (!Number.isNaN(numValue)) {
			setLocalValue(`${numValue}x`);
			onQuantityChange(tierId, numValue);
		}
	};

	return (
		<div ref={wrapperRef}>
			<TextInput
				type="text"
				value={localValue}
				onChange={handleChange}
				style={{
					margin: 0,
					textAlign: "center",
					height: "2.5em",
					cursor: "text",
				}}
			/>
		</div>
	);
}

