import { Currency } from "@/enum/currency";
import useCurrencyConversion from "@/hooks/currencies/useCurrencyConversion";
import useNotificationActions from "@/stateManagement/actions/useNotificationActions";
import { useAddProductCostMutation } from "@/stateManagement/reducers/queries/api";
import { addYears, startOfToday, subYears } from "date-fns";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useStore } from "zustand";
import { useServerSettings } from "~/components/compound/Topbar/components/serverSettingsStore";
import type { FieldType, FieldValue } from "./components/ProductCostForm/types";
import { productFormFields } from "./data";

// Todo: erase this hook and/or add columns directly to ProductCostForm
export default function useProductCostForm({
	products,
	submitButtonText,
	onSuccess,
}: {
	products: string[];
	submitButtonText: string;
	onSuccess?: () => void;
}) {
	const [addProductCost, { isLoading: isSubmitting }] = useAddProductCostMutation();

	const { notify } = useNotificationActions();
	const { currency, isLoadingIntegrationSetMe } = useCurrencyConversion();

	const settings = useServerSettings();
	const isGlobal = useStore(settings, s => s.isGlobal);

	const [selectedCurrency, setSelectedCurrency] = useState<Currency | undefined>(Currency.USD);

	useEffect(() => {
		setSelectedCurrency(prev => prev ?? currency ?? Currency.USD);
	}, [currency]);

	useEffect(() => {
		if (!isGlobal) {
			setSelectedCurrency(Currency.BRL);
		}
	}, [isGlobal]);

	const [startPermanentDuration, setStartPermanentDuration] = useState<boolean>(true);
	const [endPermanentDuration, setEndPermanentDuration] = useState<boolean>(true);

	const [country, onCountryChanged] = useState("");
	const [startDate, onStartDateChanged] = useState<Date>(startOfToday());
	const [endDate, onEndDateChanged] = useState<Date>();
	const [cost, onCostChanged] = useState<number | undefined>();
	const [shipping, onShippingChanged] = useState<number | undefined>();

	const submitDisabled = useMemo(
		() =>
			!selectedCurrency ||
			(!startDate && !startPermanentDuration) ||
			(!endDate && !endPermanentDuration) ||
			!cost,
		[selectedCurrency, startDate, startPermanentDuration, endDate, endPermanentDuration, cost],
	);

	const onSubmitForm = useCallback(async () => {
		if (submitDisabled) {
			return;
		}

		const _startDate = startPermanentDuration ? subYears(startOfToday(), 1000) : startDate!;
		const _endDate = endPermanentDuration ? addYears(startOfToday(), 1000) : endDate!;

		try {
			await addProductCost({
				cost: {
					country,
					currency: selectedCurrency!,
					endDate: _endDate,
					price: cost || 0,
					products,
					shipping: shipping || 0,
					startDate: _startDate,
				},
			}).unwrap();

			if (onSuccess) {
				onSuccess();
			}

			notify(
				"Operação concluída",
				"success",
				"A operação pode demorar alguns segundos para ser exibida.",
			);
		} catch {
			notify("Falha", "error", "Erro ao aplicar custos de produto");
		}
	}, [
		addProductCost,
		cost,
		country,
		endDate,
		endPermanentDuration,
		notify,
		onSuccess,
		products,
		selectedCurrency,
		shipping,
		startDate,
		startPermanentDuration,
		submitDisabled,
	]);

	const formValues = useMemo(() => {
		const values: Record<string, FieldValue<FieldType>> = {
			cost: {
				currency: isLoadingIntegrationSetMe ? undefined : selectedCurrency,
				value: cost?.toString(),
			},
			country: {
				value: country,
			},
			endDate: {
				checked: endPermanentDuration,
				date: endDate,
			},
			shipping: {
				currency: isLoadingIntegrationSetMe ? undefined : selectedCurrency,
				value: shipping?.toString(),
			},
			startDate: {
				checked: startPermanentDuration,
				date: startDate,
			},
		};

		return values;
	}, [
		cost,
		country,
		endDate,
		endPermanentDuration,
		isLoadingIntegrationSetMe,
		selectedCurrency,
		shipping,
		startDate,
		startPermanentDuration,
	]);

	const endDisabledDates = useCallback(
		(date: Date) => {
			if (startPermanentDuration) {
				return false;
			}
			return startDate ? date < startDate : false;
		},
		[startDate, startPermanentDuration],
	);

	const formFields = useMemo(
		() =>
			productFormFields({
				endDisabledDates,
				endPermanentDuration,
				isSubmitting,
				startPermanentDuration,
				submitButtonText,
				submitDisabled,
			}),
		[
			endDisabledDates,
			endPermanentDuration,
			isSubmitting,
			startPermanentDuration,
			submitButtonText,
			submitDisabled,
		],
	);

	const onFormValueChange = useCallback((name: string, value: FieldValue<FieldType>) => {
		const dateValue = value as Exclude<FieldValue<"dateWithCheck">, undefined>;
		const currencyValue = value as Exclude<FieldValue<"currency">, undefined>;

		switch (name) {
			case "country":
				onCountryChanged(value as string);
				break;
			case "cost":
				onCostChanged(Number((value as Exclude<FieldValue<"currency">, undefined>).value));

				if (currencyValue.currency) {
					setSelectedCurrency(currencyValue.currency);
				}
				break;
			case "shipping":
				onShippingChanged(Number((value as Exclude<FieldValue<"currency">, undefined>).value));
				if (currencyValue.currency) {
					setSelectedCurrency(currencyValue.currency);
				}
				break;
			case "startDate":
				if (dateValue.date) {
					onStartDateChanged(dateValue.date);
				}
				setStartPermanentDuration(dateValue.checked);

