		extra: { tooltip?: ReactNode };
		props: Omit<ComponentProps<typeof Button>, "label">;
		value: never;
	};
	text: {
		props: ComponentProps<typeof TextInput>;
		value: string;
	};
}

export type FieldType = keyof FieldTypeRegistry;
export type FieldValue<T extends FieldType> = FieldTypeRegistry[T]["value"];

export type Field<T extends FieldType = FieldType> = T extends any
	? {
			label: string;
			name: string;
			props?: FieldTypeRegistry[T]["props"];
			required?: boolean;
			type: T;
		} & (FieldTypeRegistry[T] extends { extra: infer E } ? E : {})
	: never;

import type { Field, FieldType } from "./components";

