import { addYears, startOfToday, subYears } from "date-fns";
import { useCallback, useMemo, useState } from "react";
import { Currency } from "@/enum/currency";
import useModalActions from "@/stateManagement/actions/useModalActions";
import useNotificationActions from "@/stateManagement/actions/useNotificationActions";
import type { CreateKitParametersProductWithData } from "@/types/entities/kit";
import type { Product } from "@/types/entities/product/product";
import isDurationPermanent from "@/utils/isDurationPermanent";
import type { EditKitModalProps, KitProductData } from "./types";
import { useProductCostsControllerCreate, useProductCostsControllerUpdateSingle } from "@lib/api";

export default function useHandler({ from, onClose }: EditKitModalProps) {
	const isEditing = useMemo(() => !!from, [from]);

	const { mutateAsync: updateKit } = useProductCostsControllerUpdateSingle();
	const { isPending, mutateAsync: createKit } = useProductCostsControllerCreate();
	const { notify } = useNotificationActions();
	const { close } = useModalActions();

	const [products, setProducts] = useState<(CreateKitParametersProductWithData & { uniqueId?: string })[]>(
		from?.products.map(product => {
			const uniqueId =
				from?.type === "SINGLE"
					? `${product.id}-${product.count}-${product.quantityModifier || "default"}`
					: undefined;

			return {
				name: product.name,
				picture: { src: product.picture.src },
				id: product.externalId,
				count: product.count,
				variantId: product.acceptedVariants.length > 1 ? "all" : product.acceptedVariants[0],
				variants: product.variants?.map(({ id }) => id),
				productId: product.externalId,
				quantityModifier: product.quantityModifier,
				price: product.price,
				shipping: product.shipping,
				...(uniqueId && { uniqueId }),
			};
		}) || [],
	);
	const [selectedCurrency, setSelectedCurrency] = useState<Currency>(from?.currency || Currency.USD);
	const [country, setCountry] = useState<string>(from?.country ?? "");
	const [selectingProduct, setSelectingProduct] = useState(false);
	const [name, setName] = useState(from?.name || "");
	const [price, setPrice] = useState(from?.price || 0);
	const [shipping, setShipping] = useState(from?.shipping || 0);
	const [permanentDuration, setPermanentDuration] = useState(
		from ? isDurationPermanent(from.endDate) : false,
	);
	const [startPermanentDuration, setStartPermanentDuration] = useState(
		from ? isDurationPermanent(from.startDate) : false,
	);
	const [interval, setInterval] = useState<[Date | undefined, Date | undefined] | undefined>(
		from
			? [
					isDurationPermanent(from.startDate) ? undefined : from.startDate,
					isDurationPermanent(from.endDate) ? undefined : from.endDate,
				]
			: [startOfToday(), undefined],
	);

