			picture: { src: product.picture || "" },
			id: product.externalId,
			count: 1,
			variantId: "all",
			productId: product.externalId,
			variants: product.variants,
		};

		setProducts(prev => [...prev, selection]);
		setSelectingProduct(false);
	}, []);

	const onSubmit = useCallback(async () => {
		if (!name.trim()) {
			notify("Preencha o nome do kit.", "error", "Informe um nome para o kit.");
			return;
		}

		if (price === null || price === undefined || price <= 0) {
			notify("Preencha o valor do kit.", "error", "Informe um custo maior que 0.");
			return;
		}

		if (!products.length) {
			notify("Adicione pelo menos um produto.", "error", "Selecione um produto para compor o kit.");
			return;
		}

		if (!interval?.[0] && !startPermanentDuration) {
			notify(
				"Adicione uma data de início para o kit.",
				"error",
				"Defina a data de início ou marque como permanente.",
			);
			return;
		}

		if (!interval?.[1] && !permanentDuration) {
			notify(
				"Adicione uma data de fim para o kit.",
				"error",
				"Defina a data de fim ou marque como permanente.",
			);
			return;
		}

		const _startDate = startPermanentDuration ? subYears(startOfToday(), 1000) : interval![0]!;

		const _endDate = permanentDuration ? addYears(startOfToday(), 1000) : interval![1]!;

		try {
			const kitType = from?.type || "MULTIPLE";

			if (kitType === "SINGLE") {
				const productId = products[0]?.id;
				if (!productId) {
					notify("Erro", "error", "Selecione um produto.");
