							shipping: itemShipping || shipping || 0,
						};
					},
				);

				await createKit({
					data: {
						country,
						currency: selectedCurrency,
						endDate: _endDate,
						items,
						name: name.trim(),
						product: productId,
						startDate: _startDate,
						type: "SINGLE",
					},
				});
			} else {
				const items = products.map(({ id, count, variantId, variants, quantityModifier }) => {
					const selectedVariants: string[] =
						variantId === "all" ? variants || [] : variantId ? [variantId] : [];

					return {
						productId: id,
						quantity: count,
						variants: selectedVariants,
						quantityModifier: quantityModifier || "EQ",
					};
				});

				if (isEditing) {
					await updateKit({
						data: {
							country,
							costId: from!.id,
							endDate: _endDate,
							items: from!.items.map(item => ({
								...item,
								variants: item.variants?.map(v => v.id) ?? null,
							})),
							name: name.trim(),
							optionId: from!.optionId,
							price,
							shipping,
							startDate: _startDate,
						},
					});
				} else {
					await createKit({
						data: {
							country,
							currency: selectedCurrency,
							endDate: _endDate,
							items,
							name: name.trim(),
							price,
							shipping,
							startDate: _startDate,
							type: "MULTIPLE",
						},
					});
				}
			}

			notify(
				isEditing ? "Kit atualizado com sucesso!" : "Kit criado com sucesso!",
				"success",
				isEditing ? "O kit foi atualizado com sucesso." : "O kit foi criado com sucesso.",
			);
			onClose?.();
			close();
		} catch (error) {
			notify(
				isEditing ? "Erro ao atualizar o kit" : "Erro ao criar o kit",
				"error",
				"Tente novamente mais tarde.",
			);
		}
	}, [
		close,
		country,
		createKit,
		from,
		interval,
		isEditing,
		name,
		notify,
		onClose,
