import { addYears, startOfToday, subYears } from "date-fns";
import { useCallback, useState } from "react";
import { Currency } from "@/enum/currency";
import useNotificationActions from "@/stateManagement/actions/useNotificationActions";
import type { Product } from "@/types/entities/product/product";
import isDurationPermanent from "@/utils/isDurationPermanent";
import type { PriceTier, SingleProductKitModalProps } from "./types";
import { useProductCostsControllerCreate, useProductCostsControllerUpdateSingle } from "@lib/api";

export default function useHandler({ action, from, onClose }: SingleProductKitModalProps) {
	const isCreating = action === "create";
	const isEditing = action === "edit";

	const { notify } = useNotificationActions();
	const { isPending: isSubmitting, mutateAsync: createKit } = useProductCostsControllerCreate();
	const { mutateAsync: updateKit } = useProductCostsControllerUpdateSingle();

	const [selectedProduct, setSelectedProduct] = useState<Product | null>(from?.product ?? null);
	const [selectingProduct, setSelectingProduct] = useState(false);
	const [selectedCurrency, setSelectedCurrency] = useState<Currency>(from?.currency || Currency.USD);
	const [country, setCountry] = useState<string>(from?.country ?? "");

	const [priceTiers, setPriceTiers] = useState<PriceTier[]>(
		isEditing
			? from!.items.map(tier => ({ id: crypto.randomUUID(), ...tier }))
			: [
					{
						id: crypto.randomUUID(),
						operator: "EQ",
						quantity: 1,
						cost: 0,
						shipping: 0,
					},
				],
	);

	const [startPermanentDuration, setStartPermanentDuration] = useState(
		from ? isDurationPermanent(from.startDate) : false,
	);
	const [endPermanentDuration, setEndPermanentDuration] = useState(
		from ? isDurationPermanent(from.endDate) : false,
	);
	const [startDate, setStartDate] = useState<Date | undefined>(
		from ? (isDurationPermanent(from.startDate) ? undefined : from.startDate) : startOfToday(),
	);
	const [endDate, setEndDate] = useState<Date | undefined>(
		from ? (isDurationPermanent(from.endDate) ? undefined : from.endDate) : undefined,
	);

	const onProductSelected = useCallback((product: Product | null) => {
		if (!product) return;
		setSelectedProduct(product);
		setSelectingProduct(false);
	}, []);

	const onRemoveProduct = useCallback(() => {
		setSelectedProduct(null);
	}, []);

	const onAddTier = useCallback(() => {
		const lastTier = priceTiers[priceTiers.length - 1];
		const newQuantity = lastTier ? lastTier.quantity + 1 : 1;

		setPriceTiers(prev => {
			const updatedPrev = prev.map((tier, index) =>
				index === prev.length - 1 && tier.operator === "GT"
					? { ...tier, operator: "EQ" as const }
					: tier,
			);

			return [
				...updatedPrev,
				{
					id: crypto.randomUUID(),
					operator: "EQ",
					quantity: newQuantity,
					cost: 0,
					shipping: 0,
				},
			];
		});
	}, [priceTiers]);

	const onRemoveTier = useCallback((id: string) => {
		setPriceTiers(prev => prev.filter(tier => tier.id !== id));
	}, []);

	const onTierQuantityChange = useCallback((id: string, quantity: number) => {
		setPriceTiers(prev =>
			prev.map(tier => (tier.id === id ? { ...tier, quantity: Math.max(1, quantity) } : tier)),
		);
	}, []);

	const onTierCostChange = useCallback((id: string, cost: number) => {
		setPriceTiers(prev => prev.map(tier => (tier.id === id ? { ...tier, cost } : tier)));
	}, []);

	const onTierShippingChange = useCallback((id: string, shipping: number) => {
		setPriceTiers(prev => prev.map(tier => (tier.id === id ? { ...tier, shipping } : tier)));
	}, []);

	const onTierOperatorChange = useCallback((id: string, operator: "EQ" | "GT") => {
		setPriceTiers(prev => {
			const tierIndex = prev.findIndex(tier => tier.id === id);
			const isLastTier = tierIndex === prev.length - 1;
			const isOnlyTier = prev.length === 1;

			if (operator === "GT" && !isLastTier && !isOnlyTier) {
				return prev;
			}

			return prev.map(tier => (tier.id === id ? { ...tier, operator } : tier));
		});
	}, []);

	const onSubmit = useCallback(async () => {
		const isValidKit =
			priceTiers.length > 1 ||
			priceTiers.some(each => each.operator !== "EQ") ||
			priceTiers.some(each => each.quantity > 1);
		if (!isValidKit) {
			notify(
				"Configuração de kit inválida.",
				"error",
				"É necessário ter mais de 1 regra ou que inclua 'Maior'.",
			);
			return;
		}

		if (!selectedProduct) {
			notify("Selecione um produto.", "error", "Você precisa selecionar um produto para criar o kit.");
			return;
		}

		const combinations = priceTiers.map(t => `${t.operator || "EQ"}-${t.quantity}`);
		const hasDuplicateCombinations = new Set(combinations).size !== combinations.length;
		if (hasDuplicateCombinations) {
			notify(
				"Combinações repetidas.",
				"error",
				"Não pode haver duas entradas com a mesma regra e quantidade.",
			);
			return;
		}
		if (priceTiers.length === 0) {
			notify(
				"Adicione pelo menos uma combinação.",
				"error",
				"Configure pelo menos uma quantidade com custo e frete.",
			);
			return;
		}

		const hasGTInWrongPosition = priceTiers.some(
			(tier, index) =>
				tier.operator === "GT" && index !== priceTiers.length - 1 && priceTiers.length > 1,
		);
		if (hasGTInWrongPosition) {
			notify(
				"Regra 'Maior' inválida.",
				"error",
				"A regra 'Maior' só pode ser usada sozinha ou na última posição.",
			);
			return;
		}

		// Impede quantidades repetidas entre os tiers
		const quantities = priceTiers.map(t => t.quantity);
		const hasDuplicateQuantities = new Set(quantities).size !== quantities.length;
		if (hasDuplicateQuantities) {
			notify(
				"Quantidades repetidas.",
				"error",
				"As quantidades devem ser diferentes em cada combinação.",
			);
			return;
		}

		const hasInvalidTier = priceTiers.some(tier => tier.cost <= 0 || tier.quantity <= 0);

		if (hasInvalidTier) {
			notify(
				"Valores inválidos.",
				"error",
				"Todas as combinações devem ter quantidade e custo maiores que zero.",
			);
			return;
		}

		if (!startDate && !startPermanentDuration) {
			notify(
				"Adicione uma data de início.",
				"error",
				"Defina a data de início ou marque como permanente.",
			);
			return;
		}

