import { PrismaService } from "@infra";
import { Injectable } from "@nestjs/common";
import { getTotalPages } from "@shared/utils";
import { TraceClass } from "@utils/tracing";
import { ProductCostType } from "sql";
import { ListProductCostsDTO, ListProductCostsReturn } from "../dtos";
import { ProductCostRepository, VariantRepository } from "../repositories";
import { VariantInfo, VariantInfoCosts } from "../types";
import { ProductCostUtils } from "../utils";
import { findSingleCosts } from "../utils/funcs";

@Injectable()
@TraceClass()
export class ListProductCosts {
	constructor(
		private readonly prisma: PrismaService,
		private readonly productCostRepository: ProductCostRepository,
		private readonly productCostUtils: ProductCostUtils,
		private readonly variantRepository: VariantRepository,
	) {}

	async execute({
		country,
		credentials: {
			current: { virtualStoreId },
		},
		kits,
		limit,
		mapKey,
		onlyFilled,
		page,
		productIds,
		search,
		type,
		variantIds,
	}: ListProductCostsDTO): Promise<ListProductCostsReturn> {
		const paginated = limit && page;

		let productsSet = await this.productCostUtils.searchProducts(search);

		if (productIds) {
			productsSet ??= new Set();
			productIds.forEach(id => productsSet?.add(id));
		}

		const [{ productCosts, total }, countryOptions, variantInfo] = await Promise.all([
			this.productCostRepository.find({
				country,
				productIds: productsSet && Array.from(productsSet),
				search,
				sort: [{ endDate: "desc" }, { startDate: "desc" }],
