const onSubmit = useCallback(async () => {
	if (!name.trim()) {
		notify("Preencha o nome do kit.", "error", "Informe um nome para o kit.");
		return;
	}

	if (price === null || price === undefined || price <= 0) {
		notify("Preencha o valor do kit.", "error", "Informe um custo maior que 0.");
		return;
	}

	if (!products.length) {
		notify("Adicione pelo menos um produto.", "error", "Selecione um produto para compor o kit.");
		return;
	}

	const _startDate = startPermanentDuration ? subYears(startOfToday(), 1000) : interval![0]!;
	const _endDate = permanentDuration ? addYears(startOfToday(), 1000) : interval![1]!;

	try {
		const kitType = from?.type || "MULTIPLE";

		if (kitType === "SINGLE") {
			// SINGLE kit creation logic
		} else {
			const items = products.map(({ id, count, variantId, variants, quantityModifier }) => {
				const selectedVariants: string[] =
					variantId === "all" ? variants || [] : variantId ? [variantId] : [];

				return {
					productId: id,
					quantity: count,
					variants: selectedVariants,
					quantityModifier: quantityModifier || "EQ",
				};
			});

			await createKit({
				data: {
					country,
					currency: selectedCurrency,
					endDate: _endDate,
					items,
					name: name.trim(),
					price,
					shipping,
					startDate: _startDate,
					type: "MULTIPLE",
				},
			});
		}

		notify("Kit criado com sucesso!", "success", "O kit foi criado com sucesso.");
		onClose?.();
	} catch (error) {
		notify("Erro ao criar o kit", "error", "Tente novamente mais tarde.");
	}
}, [
	country,
	createKit,
	from,
	interval,
	isEditing,
	name,
	notify,
	onClose,
	permanentDuration,
	price,
	products,
	selectedCurrency,
	shipping,
	startPermanentDuration,
]);
