"use client";
import * as countryFlags from "country-flag-icons/react/3x2";
import countries, { getName } from "i18n-iso-countries";
import ptCountries from "i18n-iso-countries/langs/pt.json";
import { Globe } from "lucide-react";
import DashboardDropdownAlt from "@/components/simple/DashboardDropdownAlt";

countries.registerLocale(ptCountries);

const countryCodes = Object.keys(countries.getAlpha2Codes())
	.filter((countryCode) => (countryFlags as any)[countryCode])
	.sort((codeA, codeB) => {
		const a = getName(codeA, "pt") ?? codeA;
		const b = getName(codeB, "pt") ?? codeB;
		return a.localeCompare(b, "pt");
	});

const countryOptions = ["", ...countryCodes];

export default function CountrySelect({
	value,
	onChange,
	className,
}: {
	value: string;
	onChange: (value: string) => void;
	className?: string;
}) {
	return (
		<DashboardDropdownAlt
			className={className ?? "!w-full h-10 rounded-[8px]"}
			displayFunc={(value: string) => {
				const FlagComponent = value && (countryFlags as any)[value];

				return FlagComponent ? <FlagComponent className="h-6" /> : <Globe />;
			}}
			dropdownClassName="!pl-3 flex mx-auto"
			expandIcon
			noFuzzy
			onChange={(itemValue) => onChange(itemValue as string)}
			// @ts-expect-error options display accepts ReactNode but is typed as string
			options={countryOptions.map((countryCode) => {
				const FlagComponent = (countryFlags as any)[countryCode];
				const countryName = countryCode ? getName(countryCode, "pt") : "Global";

				return {
					display: (
						<div className="grid h-8 w-full grid-cols-[2.5rem_1fr] items-center gap-4 [&>svg]:h-full">
							{FlagComponent ? (
								<FlagComponent />
							) : (
								<Globe className="mx-auto h-8 w-8" />
							)}
							<span className="color-white">{countryName}</span>
						</div>
					),
					label: countryName,
					value: countryCode,
				};
			})}
			searchBar
			stopSearchPropagation
			value={value}
		/>
	);
}
