### 2. Country Filtering on Kits Screen

**YES — Kits screen has country filtering AND date selection, using REUSED components from Product Cost.**

**Country Filter Component for Kits:** `/Users/work/Desktop/Projetos/bk-company/bk-dash-frontend/src/app/app/product/kits/components/KitsCountryFilter.tsx`

```typescript
"use client";
import i18nCountries from "i18n-iso-countries";
import enCountries from "i18n-iso-countries/langs/en.json";
import { parseAsString, useQueryState } from "nuqs";
import { useMemo } from "react";
import Button from "@/components/simple/Button";
import { ButtonLimiter } from "~/app/app/settings/integration/style";

i18nCountries.registerLocale(enCountries);

export function KitsCountryFilter({ countries }: { countries: string[] }) {
	const [country, setCountry] = useQueryState(
		"country",
		parseAsString.withDefault(""),
	);

	const countryInfo = useMemo<[string, string][]>(
		() => [
			["", "Global"],
			...countries
				.map((code): [string, string] => [
					code,
					i18nCountries.getName(code, "en") ?? code,
				])
				.sort(([, a], [, b]) => a.localeCompare(b, "en")),
		],
		[countries],
	);

	return (
		<div className="w-full rounded-[8px] bg-[#1f212a] p-2">
			<div className="grid w-fit auto-cols-fr grid-flow-col justify-start gap-4">
				{countryInfo.map(([countryCode, countryName]) => {
					const selected = countryCode === country;
					return (
						<ButtonLimiter
							className="flex items-center"
							key={countryCode}
							selected={selected}
						>
							<Button
								className="h-full w-full min-w-30"
								label={countryName}
								onClick={() => setCountry((!selected && countryCode) || null)}
								type="tertiary"
							/>
						</ButtonLimiter>
					);
				})}
			</div>
		</div>
	);
}
```

**Key Observations:**
- **IDENTICAL pattern to Product Cost** — same `useQueryState("country")` with `i18nCountries` library
- **Simpler implementation** — no `setFilters` callback like Product Cost
- **Integrated in page:** Passed directly to `<KitsBeforeTable>` component
- **URL-driven:** Same `?country=` query parameter

