import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { mockId } from '@shared/testing/mock'

export const CreateKitInputSchema = z.object({
	storeId: z.uuid(),
	name: z.string(),
	type: z.enum(ProductCostType),
	shipping: z.number(),
	cost: z.number().optional(),
	items: z.array(
		z.object({
			productId: z.uuid(),
			quantity: z.number(),
			quantityModifier: z.enum(QuantityModifier),
		}),
	),
})

export const CreateKitOutputSchema = z.object({
	id: z.uuid(),
	success: z.boolean(),
})

/** MOCK. Create a kit (wizard command). Returns static success. */
@injectable()
export class CreateKit extends Handler<typeof CreateKitInputSchema, typeof CreateKitOutputSchema> {
	readonly name = 'create_kit' as const
	readonly inputSchema = CreateKitInputSchema
	readonly outputSchema = CreateKitOutputSchema

	protected async handle(_input: this['input']): Promise<this['output']> {
		return { id: mockId(), success: true }
	}
}

